// ════════════════════════════════════════════════════════════════════
//  วาดกระดาษบนจอออกมาเป็นภาพ — ★ ตัวเดียวที่ทั้งของจริงและตัวตรวจใช้ร่วมกัน
//
//  ★★ ความคมของตัวโน้ตอยู่ที่ไฟล์นี้ ★★ เจ้าของย้ำ 2026-08-20:
//    "ความคมคือหัวใจ เอาไปใช้แล้วต้องดูออกว่าโน้ตอะไร"
//    → ทุกครั้งที่แก้ไฟล์นี้ ให้รัน `.scratch/ui-probes/tile.mjs` ดูภาพจริงก่อนเสมอ
//      **ถูกตำแหน่งก่อน แล้วค่อยดูว่าคม** — เคยได้ภาพคมที่ครอบผิดช่วงมาแล้ว
// ════════════════════════════════════════════════════════════════════

/** ฟอนต์ที่กระดาษใช้จริง — ตัวอื่นในหน้าไม่ต้องฝัง (เปลืองเวลาและขนาดเปล่า ๆ) */
export const NEEDED = ['Anuphan', 'IBM Plex Sans Thai', 'Bravura'];

/** เก็บ `@font-face` ของหน้าจริงแล้วแปลง url() เป็น data URI
 *  ★ อ่านจาก `document.styleSheets` ไม่ใช่ hardcode ชื่อไฟล์ — ชื่อไฟล์ฟอนต์มี hash
 *    ต่อท้ายและถูกสร้างใหม่ทุกครั้งที่อัปเดตฟอนต์ (ดูหัวไฟล์ styles/fonts.css) */
export async function embedFontCss(): Promise<{ css: string; bytes: number; count: number }> {
  const jobs: Array<Promise<string>> = [];
  for (const sheet of Array.from(document.styleSheets)) {
    let rules: CSSRuleList;
    try { rules = sheet.cssRules; } catch { continue; }   // สไตล์ข้ามโดเมนอ่านไม่ได้
    for (const rule of Array.from(rules)) {
      if (!(rule instanceof CSSFontFaceRule)) continue;
      const fam = rule.style.getPropertyValue('font-family').replace(/['"]/g, '').trim();
      if (!NEEDED.some((n) => fam.toLowerCase() === n.toLowerCase())) continue;
      const src = rule.style.getPropertyValue('src');
      const url = /url\(["']?([^"')]+)["']?\)/.exec(src)?.[1];
      if (!url) continue;
      jobs.push((async () => {
        const buf = await (await fetch(url)).arrayBuffer();
        let bin = '';
        const b = new Uint8Array(buf);
        for (let i = 0; i < b.length; i += 1) bin += String.fromCharCode(b[i]);
        const data = `data:font/woff2;base64,${btoa(bin)}`;
        return rule.cssText.replace(/url\(["']?[^"')]+["']?\)/, `url(${data})`);
      })());
    }
  }
  const parts = await Promise.all(jobs);
  const css = parts.join('\n');
  return { css, bytes: css.length, count: parts.length };
}

/** ★★ CSS ของหน้าทั้งหมด — **ขาดไม่ได้** ★★
 *  ของใน `<foreignObject>` **ไม่เห็นสไตล์ชีตของหน้า** เห็นแค่ที่ฝังมากับ SVG
 *  ฝังแต่ฟอนต์ (รอบแรก 2026-08-19) → ตัวหนังสือขึ้นถูกแต่ **ตารางพังทั้งใบ**
 *  กลายเป็นรายการเรียงลงมา · บนจอดูปกติทุกอย่าง ภาพที่ได้ถึงจะผิด
 *  ★ ตัวเลขความเร็วที่วัดจากภาพพัง **ใช้ไม่ได้** — SVG เล็กกว่าความจริงมาก
 *  ★ ตัด @font-face ของเดิมทิ้ง (ชี้ไฟล์ที่ SVG โหลดไม่ได้) ใช้ตัวที่ฝัง data URI แทน */
export function pageCss(): string {
  const out: string[] = [];
  for (const sheet of Array.from(document.styleSheets)) {
    let rules: CSSRuleList;
    try { rules = sheet.cssRules; } catch { continue; }
    for (const rule of Array.from(rules)) {
      if (rule instanceof CSSFontFaceRule) continue;
      out.push(rule.cssText);
    }
  }
  return out.join('\n');
}

/** ★★ ตัวแปร CSS (`--color-…`) ประกาศไว้ที่ `:root` ★★
 *  ในภาพ ก้อนที่โคลนมาเป็น **ราก** ของต้นไม้นั้นเอง — ตัวเลือก `:root`/`html`
 *  จึงไม่ตรงกับอะไรเลย แล้วสีทั้งแผ่นหายไปหมด · ต้องคัดค่าที่คำนวณแล้วมาแปะเอง */
export function rootVars(): string {
  const cs = getComputedStyle(document.documentElement);
  const out: string[] = [];
  for (let i = 0; i < cs.length; i += 1) {
    const name = cs[i];
    if (name.startsWith('--')) out.push(`${name}:${cs.getPropertyValue(name)}`);
  }
  return out.join(';');
}

/** ★★ แผ่นสากลต้องวาด **ตรง ๆ แบบ SVG** ห้ามยัดใน <foreignObject> ★★
 *  เอนจินพ่น `<svg>` ที่มีแต่ `viewBox` **ไม่มี width/height** (ตั้งใจ — ให้ CSS
 *  ยืดเต็มความกว้างเสมอ ดู WesternSheet.tsx) · พอเอาไปวางใน foreignObject
 *  มันไม่มี CSS ของหน้าให้ยืดตาม เลย **ยุบเหลือความสูงศูนย์** = ภาพว่างเปล่า
 *  โดยไม่มี error อะไรเลย (เจอ 2026-08-19: รายงานว่า "แผ่นสากลติดมาด้วย" แต่ภาพโล่ง)
 *  → โคลนมาแล้วใส่ width/height จริงลงไปเอง + ฝัง CSS ไว้ข้างใน */
export function svgDirect(
  el: SVGElement, css: string, vars: string, outW?: number,
): { svg: string; w: number; h: number } {
  const box = el.getBoundingClientRect();
  const vb = (el.getAttribute('viewBox') || '').split(/\s+/).map(Number);
  const w = Math.round(box.width || vb[2] || 800);
  const h = Math.round(box.height || vb[3] || 600);
  const clone = el.cloneNode(true) as SVGElement;
  // ★ แผ่นสากลเก็บไฮไลต์เป็น **แอตทริบิวต์ `fill` ตรง ๆ** (ดู playhead.paintSelectedBar)
  //   CSS จึงล้างไม่ได้ ต้องล้างที่ตัวสำเนาเอง — เหตุผลเดียวกับฝั่งกระดาษไทย
  clone.querySelectorAll('.wn-hl').forEach((h) => {
    h.classList.remove('wn-sel', 'wn-hl-play');
    h.setAttribute('fill', 'transparent');
  });
  // ★ ขอภาพเป็นพิกเซลเท่าที่จะวาดจริง — SVG ยืดตาม viewBox ให้เอง จึงคมที่ทุกขนาด
  const kk = outW ? outW / w : 1;
  clone.setAttribute('width', String(Math.round(w * kk)));
  clone.setAttribute('height', String(Math.round(h * kk)));
  clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  const style = document.createElementNS('http://www.w3.org/2000/svg', 'style');
  style.textContent = `.tsvars{${vars}}\n${css}`;
  clone.insertBefore(style, clone.firstChild);
  clone.setAttribute('class', `${clone.getAttribute('class') || ''} tsvars`.trim());
  return { svg: new XMLSerializer().serializeToString(clone), w, h };
}

/** DOM หนึ่งก้อน → ภาพหนึ่งใบ ผ่าน <foreignObject> */
/** @param box  ขนาดจริงของก้อน DOM (หน่วย CSS)
 *  @param out  ขนาดภาพที่ต้องการเป็นพิกเซล
 *  @param crop ช่วงบนก้อนนั้นที่จะเอา (หน่วย CSS) — ไม่ส่ง = ทั้งก้อน
 *  ★★ ความคมของตัวโน้ตอยู่ที่นี่ ★★ เดิม rasterize ครั้งเดียวเท่าขนาดบนจอ
 *    (~1080 px) แล้ว **ขยายตอนวาด** — แบบซูมขยายถึง 3.5 เท่า ตัวโน้ตจึงเบลอ
 *    (เจ้าของทัก 2026-08-20) · `viewBox` ตัดเฉพาะช่วงที่ใช้แล้วยืดให้เต็ม `out`
 *    → ได้ภาพ **ตรงขนาดที่จะวาดจริง 1:1** ไม่ต้องขยายอีกเลย
 *  ★ ทำเป็นชิ้น ๆ ตามช่วงที่ใช้ ไม่ใช่ทั้งแผ่นที่ความละเอียดสูง เพราะเพลงยาว
 *    54 บรรทัด × 3 เท่า จะเกินเพดานขนาด canvas ของ WebKit ไปไกล */
export function svgFor(
  el: HTMLElement, box: { w: number; h: number }, out: { w: number; h: number },
  css: string, vars: string, crop?: { x: number; y: number; w: number; h: number },
) {
  const c = crop || { x: 0, y: 0, w: box.w, h: box.h };
  const clone = el.cloneNode(true) as HTMLElement;
  clone.setAttribute('xmlns', 'http://www.w3.org/1999/xhtml');
  const xml = new XMLSerializer().serializeToString(clone);
  // ★★ ห้ามพึ่ง `viewBox` ในการครอบ ★★ เบราว์เซอร์ครอบให้ถูก แต่ **เอนจินของแอป
  //   (WKWebView) ย่อทั้งแผ่นให้พอดีแทน** เมื่อเนื้อหาข้างในใหญ่กว่ากรอบมาก ๆ
  //   (กระดาษ 54 บรรทัดสูง ~4,500 px แต่ขอครอบแค่ ~83 px) → ได้ภาพทั้งเพลงย่อจิ๋ว
  //   ทั้งที่ในเบราว์เซอร์ภาพเดียวกันถูกต้อง (2026-08-20)
  //   → สั่ง **เลื่อนแล้วขยายตรง ๆ** ด้วย transform ซึ่งไม่มีที่ให้ตีความต่างกัน
  const k = out.w / c.w;
  const tile = `.tstile{transform:scale(${k}) translate(${-c.x}px,${-c.y}px);`
    + `transform-origin:0 0;width:${box.w}px;height:${box.h}px}`
    // ★★ สถานะของ "โปรแกรม" ห้ามติดไปในคลิป ★★ กรอบทองของช่องที่เลือกอยู่ กับ
    //   ไฮไลต์หัวเข็มบนจอ เป็นของเครื่องมือ ไม่ใช่ของโน้ต — กฎเดียวกับกระดาษพิมพ์
    //   (`@media print` ใน notation.css ล้างสองอันนี้ทิ้งด้วยเหตุผลเดียวกัน)
    //   ★ เจอจากคลิปจริง 2026-08-20: กรอบทองที่ห้อง 1 ติดไปทุกเฟรมทั้งคลิป
    //   ★ หัวเข็มของคลิปวาดทับเองทีหลัง (ดู clip_layouts.marks) ถ้าไม่ล้างของเดิม
    //     จะได้ไฮไลต์ค้างสองที่ในเฟรมเดียว
    + `\n.tstile .tn-cell.is-sel,.tstile .tn-cell.is-play,.tstile .tn-hong.is-play`
    + `{background:transparent !important;box-shadow:none !important}`;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${Math.round(out.w)}" height="${Math.round(out.h)}">`
    // ★★ ต้องห่อ CDATA ★★ เนื้อใน <style> ของ SVG ถูกอ่านแบบ **XML** —
    //   ตัวเลือกที่มี `>` (ลูกโดยตรง) หรือ `&` ในไฟล์ CSS ทำให้ทั้งภาพถอดไม่ออก
    //   แล้วได้ error กลาง ๆ ว่า "โหลดภาพไม่สำเร็จ" ซึ่งไม่บอกสาเหตุเลย
    // ★★ ตัวแปรรากต้องไปอยู่ใน <style> **ไม่ใช่แอตทริบิวต์ style="…"** ★★
    //   ค่าบางตัวมีอักขระที่ทำให้แอตทริบิวต์ XML พังทั้งไฟล์ แล้วได้แค่
    //   "โหลดภาพไม่สำเร็จ" เปล่า ๆ · ในบล็อก CDATA ไม่ต้องหนีอักขระใด ๆ เลย
    //   (ไล่หาเจอด้วยการลองทีละชั้น — เดาสองรอบก่อนหน้านั้นผิดทั้งคู่)
    // ★★★ ย่อ–เลื่อนต้องสั่งที่ **ฝั่ง HTML ข้างใน** เท่านั้น ★★★
    //   เอนจินของแอป (WKWebView) **ไม่สนใจทั้ง `viewBox` และ `transform` ของ SVG**
    //   ที่ครอบ `<foreignObject>` — ได้ภาพเป็นมุมซ้ายบนของกระดาษขนาดจริงแทน
    //   (ลองมาแล้วทั้งสองทาง 2026-08-20 · **เบราว์เซอร์ทำถูกทั้งคู่** จึงหลอกได้ง่ายมาก
    //    ต้องพิสูจน์ในแอปจริงเท่านั้น)
    //   ★ วางเป็นกฎ CSS ในบล็อก CDATA ไม่ใช่แอตทริบิวต์ `style="…"` (ดูรอยแผลข้างบน)
    + `<style><![CDATA[.tsvars{${vars}}\n${tile}\n${css}]]></style>`
    + `<foreignObject x="0" y="0" width="${Math.round(out.w)}" height="${Math.round(out.h)}">`
    + `<div xmlns="http://www.w3.org/1999/xhtml" class="tsvars tstile">${xml}</div>`
    + `</foreignObject></svg>`;
}

/** ★★ ต้องเป็น `data:` URL — **ห้ามใช้ blob URL** ★★
 *  ทั้งสองแบบถอดภาพออกเหมือนกัน แต่ **blob URL ทำให้ canvas กลายเป็นของต้องห้าม**
 *  ใน WebKit → `getImageData` โยน `SecurityError: The operation is insecure`
 *  ซึ่งแปลว่าเอาพิกเซลออกมาส่งให้ตัวเข้ารหัสไม่ได้เลย = ทำคลิปไม่ได้
 *  (พิสูจน์บน WKWebView จริง 2026-08-19 · ไม่มีในเอกสารของใคร)
 *  ★ ที่เคยคิดว่า data URL พังเพราะ "ขนาดเกินเพดาน" — **ไม่จริง** สาเหตุจริงคือ
 *    ตัวแปรรากที่ยัดลงแอตทริบิวต์ style="…" แล้วทำ XML พัง (ดู svgFor) */
export const decode = (svg: string) => new Promise<HTMLImageElement>((res, rej) => {
  const img = new Image();
  img.onload = () => res(img);
  img.onerror = () => rej(new Error('ถอดภาพ SVG ไม่สำเร็จ'));
  img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
});


/** ★★ ตัวแสดงผลสองตัวห้ามคนละอย่างกัน — ต้องถามเครื่องเอง ห้ามดูจากชื่อระบบ ★★
 *
 *  WebKit (mac) : `blob:` URL ทำให้ canvas เสีย → เลยใช้ `data:` URL (ดู decode)
 *  WebView2 (Windows) : `createImageBitmap()` ของ SVG ที่มี `<foreignObject>`
 *    **ทำให้ canvas เสีย** ทั้งที่ `data:` URL เดียวกันวาดจาก `Image` ตรง ๆ ไม่เสีย
 *    → `getImageData` โยน SecurityError = เอาพิกเซลไปให้ตัวเข้ารหัสไม่ได้เลย
 *    (พิสูจน์ในแอปจริงผ่าน CDP 2026-08-23 · ไม่มีในเอกสารของใคร)
 *
 *  ทางออกที่ใช้ได้ทั้งคู่: ถ้าเครื่องนี้ทำ ImageBitmap แล้วเสีย ให้ **แร็สเตอร์ลง
 *  canvas กลางหนึ่งใบ** แล้วใช้ canvas ใบนั้นเป็นต้นทางแทน — วาดจาก canvas ที่สะอาด
 *  ไม่ทำให้ปลายทางเสีย และยังวาดซ้ำได้เร็วเท่า ImageBitmap (ไม่ต้องถอด SVG ใหม่ทุกครั้ง)
 */
let bitmapClean: Promise<boolean> | null = null;
function bitmapIsClean(): Promise<boolean> {
  if (!bitmapClean) {
    bitmapClean = (async () => {
      try {
        const probe = `<svg xmlns="http://www.w3.org/2000/svg" width="2" height="2">`
          + `<foreignObject width="2" height="2"><div xmlns="http://www.w3.org/1999/xhtml"`
          + ` style="width:2px;height:2px;background:#000"></div></foreignObject></svg>`;
        const cv = document.createElement("canvas");
        cv.width = 2; cv.height = 2;
        const c = cv.getContext("2d", { willReadFrequently: true })!;
        c.drawImage(await createImageBitmap(await decode(probe)), 0, 0);
        c.getImageData(0, 0, 1, 1);
        return true;
      } catch {
        return false;
      }
    })();
  }
  return bitmapClean;
}

/** เอาภาพ SVG ที่ถอดแล้ว มาทำเป็นของที่เอาไปวาดซ้ำได้โดยไม่ทำให้ canvas เสีย */
export async function toDrawable(img: HTMLImageElement, w?: number, h?: number): Promise<CanvasImageSource> {
  if (await bitmapIsClean()) return createImageBitmap(img);
  const cv = document.createElement("canvas");
  cv.width = Math.max(1, Math.round(w || img.naturalWidth || img.width));
  cv.height = Math.max(1, Math.round(h || img.naturalHeight || img.height));
  cv.getContext("2d")!.drawImage(img, 0, 0, cv.width, cv.height);
  return cv;
}
